<?php
/**
 * Anima theme — shared header/layout (used by ALL Anima pages).
 * Home nav ported from design/master/home.html (RULE #1); nav items match the Figma design.
 * A page sets $seo (title/description) and optionally $anima_body_class ('page-inner' for non-hero
 * pages -> nav renders solid) BEFORE including this file, following the CMS page convention.
 * CSP-A: external CSS/JS only; self-hosted fonts.
 */
require_once __DIR__ . '/../../inc/anima.php';
if (!function_exists('theme_url'))   { function theme_url($p=''){ return '/themes/anima/' . ltrim($p,'/'); } }
if (!function_exists('get_setting')) { function get_setting($k,$d=''){ return $d; } }
$seo = $seo ?? [];
$__title = $seo['title']       ?? get_setting('site_title', 'Sapta Tunas Teknologi — Enterprise Solution Provider');
$__desc  = $seo['description']  ?? get_setting('site_description', 'Sapta Tunas Teknologi — established 2015. Business Technology Solutions & Services di Indonesia: IT & Cloud Infrastructure, Cybersecurity, Data & AI.');
$__body_class = trim($anima_body_class ?? '');
?>
<!DOCTYPE html>
<html lang="<?= htmlspecialchars(function_exists('current_lang') ? current_lang() : 'id') ?>">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title><?= htmlspecialchars($__title) ?></title>
<meta name="description" content="<?= htmlspecialchars($__desc) ?>">
<?php if (function_exists('is_multilang') && is_multilang()): foreach (available_langs() as $__l): ?>
<link rel="alternate" hreflang="<?= htmlspecialchars($__l) ?>" href="<?= htmlspecialchars(url($GLOBALS['__path'] ?? '', $__l)) ?>">
<?php endforeach; endif; ?>
<link rel="stylesheet" href="<?= theme_url('assets/fonts/fonts.css') ?>">
<link rel="stylesheet" href="<?= theme_url('assets/css/anima.css') ?>">
<link rel="stylesheet" href="<?= theme_url('assets/css/pages.css') ?>">
<?php if (!empty($GLOBALS['__preview_reveal'])) echo '<link rel="stylesheet" href="/preview/preview.css">'; ?>
</head>
<body<?= $__body_class ? ' class="' . htmlspecialchars($__body_class) . '"' : '' ?>>
<header>
  <nav class="nav">
    <a class="brand" href="#"><img class="brand-logo" src="data:image/png;base64," alt="Sapta Tunas Teknologi"></a>
    <?php
      // Header navigation from the CMS menu (DB), language-aware URLs + translatable labels.
      $__nav = function_exists('get_menu_tree') ? get_menu_tree() : [];
      $__mlabel = fn($m) => function_exists('tr_field') ? tr_field('menus', (int)$m['id'], 'nama', $m['nama'] ?? '') : ($m['nama'] ?? '');
      // The contact item is surfaced as the CTA button instead of a menu link.
      $__is_contact = fn($m) => in_array($m['url_raw'] ?? '', ['/hubungi-kami', 'hubungi-kami'], true);
    ?>
    <div class="menu">
      <?php foreach ($__nav as $mi): if ($__is_contact($mi)) continue;
        $kids = $mi['children'] ?? [];
        $tgt  = (($mi['target'] ?? '_self') === '_blank') ? ' target="_blank" rel="noopener"' : '';
      ?>
        <?php if ($kids): ?>
          <div class="has-sub">
            <a href="<?= htmlspecialchars($mi['url']) ?>"<?= $tgt ?>><?= htmlspecialchars($__mlabel($mi)) ?> <svg class="caret" viewBox="0 0 24 24"><path d="M6 9l6 6 6-6"/></svg></a>
            <div class="submenu">
              <?php foreach ($kids as $ck): $ctgt = (($ck['target'] ?? '_self') === '_blank') ? ' target="_blank" rel="noopener"' : ''; ?>
                <a href="<?= htmlspecialchars($ck['url']) ?>"<?= $ctgt ?>><?= htmlspecialchars($__mlabel($ck)) ?></a>
              <?php endforeach; ?>
            </div>
          </div>
        <?php else: ?>
          <a href="<?= htmlspecialchars($mi['url']) ?>"<?= $tgt ?>><?= htmlspecialchars($__mlabel($mi)) ?></a>
        <?php endif; ?>
      <?php endforeach; ?>
    </div>
    <div class="nav-right">
      <?php if (function_exists('is_multilang') && is_multilang()): ?><?= language_switcher('lang') ?><?php endif; ?>
      <a class="btn btn-primary" href="<?= url('hubungi-kami') ?>"><?= htmlspecialchars(function_exists('t') ? t('contact_us', 'Contact Us') : 'Contact Us') ?></a>
    </div>
    <button class="hamb" aria-label="Menu" aria-expanded="false"><svg class="ic" viewBox="0 0 24 24"><path d="M3 6h18M3 12h18M3 18h18"/></svg></button>
  </nav>
</header>

<!-- Mobile navigation drawer (DB menu; toggled by .hamb -> body.nav-open) -->
<div class="mnav-scrim" data-nav-close></div>
<aside class="mnav" aria-label="Mobile navigation">
  <div class="mnav-head">
    <?php if (function_exists('is_multilang') && is_multilang()): ?><?= language_switcher('lang') ?><?php endif; ?>
    <button class="mnav-x" data-nav-close aria-label="Tutup"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18M6 6l12 12"/></svg></button>
  </div>
  <nav class="mnav-list">
    <?php foreach ($__nav as $mi): if ($__is_contact($mi)) continue;
      $mkids = $mi['children'] ?? []; ?>
      <a href="<?= htmlspecialchars($mi['url']) ?>"><?= htmlspecialchars($__mlabel($mi)) ?></a>
      <?php foreach ($mkids as $ck): ?>
        <a class="mnav-sub" href="<?= htmlspecialchars($ck['url']) ?>"><?= htmlspecialchars($__mlabel($ck)) ?></a>
      <?php endforeach; ?>
    <?php endforeach; ?>
    <a class="btn btn-primary mnav-cta" href="<?= url('hubungi-kami') ?>"><?= htmlspecialchars(function_exists('t') ? t('contact_us', 'Contact Us') : 'Contact Us') ?></a>
  </nav>
</aside>
